# -*- coding: utf-8 -*-
"""docs/1.1-游戏一页纸.docx —— 按 game-docs-and-sheets-inventory.md 1.1 写。

清单要求四件事：一句话玩法 / 核心循环 / 两个互相冲突的目标 / 战绩卡。
并明令不写：市场分析、收入预测、团队介绍。
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, ROOT)

import docx_kit as k

OUT = os.path.join(ROOT, "docs", "1.1-游戏一页纸.docx")


def main():
    doc = k.new_doc("1.1 游戏一页纸 · v0.1 · 2026-11-04")
    k.title(
        doc,
        "电竞选手模拟器",
        "游戏一页纸（概念书）· v0.1 · 2026-11-04 · 平台：虎扑 AI 工坊（手机竖屏）",
    )

    k.note(
        doc,
        "只回答清单 1.1 的四件事：一句话玩法、核心循环、两个互相冲突的目标、战绩卡。"
        "不写市场分析、收入预测、团队介绍；数值只活在 P3-数值总表.xlsx，玩法细节见 2.1 GDD。",
    )

    k.h1(doc, "一", "一句话玩法")
    k.para(
        doc,
        "**你是一个 18 岁的高分路人王，每周只有三个行动格，用 240 周决定自己是成为 "
        "LPL 冠军还是查无此人。**",
    )
    k.para(
        doc,
        "玩家在手机竖屏上点三下安排一周：上分、训练、直播、休息……然后看一个 50 字的事件、"
        "两三个选项、一次掷骰。八年后得到一段生涯结局。",
    )

    k.h1(doc, "二", "核心循环")
    k.para(doc, "一周就是一圈，一圈二十秒：")
    k.table(
        doc,
        ["步骤", "玩家看到的", "玩家做的"],
        [
            ["1 看图", "六维、体力、段位名次、教练信任、伤病、钱", "判断这周最缺什么"],
            ["2 排三格", "八个行动：上分 / 专训 / 复盘 / 训练赛 / 健身 / 直播 / 商业 / 休息", "点三下，每格有标价"],
            ["3 抽事件", "50 字的场面 + 2–3 个选项 + 成功率", "选一个"],
            ["4 结算", "数值变化、一句反馈、名次升降", "看发生了什么"],
            ["5 结周", "推进到下一周，自动存档", "——"],
        ],
        [2.6, 8.4, 5.0],
        size=9,
        caption="表 1　一周五步。比赛周会多一步自动对战（胜率由全队五人均值决定）",
    )
    k.para(
        doc,
        "八年 240 周之后进入结局：一段主结局（模板）+ 几行事件尾注（你当年做过的选择）。",
    )

    k.h1(doc, "三", "两个互相冲突的目标")
    k.para(
        doc,
        "清单要求「只有一个目标的游戏必然无脑」。这游戏的两个目标抢的是**同一份资源——每周三格**：",
    )
    k.table(
        doc,
        ["目标", "想要什么", "怎么达成", "代价"],
        [
            [
                "A 打出成绩",
                "段位到王者 → 收到邀请 → 进 LPL → 拿冠军",
                "上分（12–29 体力）+ 训练赛（16–31 体力）",
                "两格就吃光体力，六维只能靠训练赛那一点点",
            ],
            [
                "B 练成高手",
                "五维全 90，任何局面都能赢",
                "专训 / 复盘 / 分路训练，按 3 / 2 / 1 点递增成本",
                "不上分就永远签不了约，一辈子在路人局里练",
            ],
        ],
        [3.2, 5.0, 4.6, 6.0],
        size=9,
        caption="表 2　两个目标不是嘴上冲突，是算术冲突：三格里放不下两份",
    )
    k.para(
        doc,
        "**这不是我编的口径，是穷举跑出来的。** 120 种排法里前十名全部同时含「上分」与「训练赛」，"
        "而不含「上分」的排法签约率是 0——你练得再强也没人认识你。第三格才是真正的取舍。",
    )
    k.para(
        doc,
        "第二个冲突是**短期与长期**：休息回体力（短期），健身提上限（长期）；直播给钱（短期），"
        "训练给属性（长期）。所有「现在有用」的选择都在偷「以后有用」的时间。",
    )

    k.h1(doc, "四", "战绩卡")
    k.para(
        doc,
        "清单把它列进一页纸，是因为它决定了玩家会不会主动发出去。这游戏已经有了它的数据来源：",
    )
    k.table(
        doc,
        ["字段", "来自哪", "例子"],
        [
            ["起止", "18 岁入行 → 退役年份", "18 岁入行，25 岁退役"],
            ["荣誉", "荣誉柜（按年份）", "1 次联赛冠军、1 次最佳新秀"],
            ["终点段位", "最终名次（不显示分数）", "打到第 41 名"],
            ["一句话", "事件尾注里最有梗的那句", "「当年采访里那句话，后来一直跟着你」"],
        ],
        [3.0, 6.4, 6.6],
        size=9,
        caption="表 3　战绩卡四个字段，全部已经存在于存档里",
    )
    k.para(
        doc,
        "**版式已定：纯文本四行，不生成图片**——平台是单文件、手机竖屏，出一张图会吃掉包体积。"
        "四行就是表 3 的四个字段，按顺序排：",
    )
    k.note(
        doc,
        "18 岁入行 · 25 岁退役 · 1 次联赛冠军 · 1 次最佳新秀 · 最终第 41 名\n"
        "「那年我在采访里说了句『我觉得四保一没问题』，后来一直跟着我。」",
    )

    doc.save(OUT)
    print("saved", OUT)


if __name__ == "__main__":
    main()
